namespace Erlang;

public sealed class HostDistribution : IDisposable
{
    private readonly object gate = new();
    private readonly ProcessRuntime runtime;
    private readonly long maximumQueuedPayloadBytes;
    private readonly int maximumQueuedBuffers;
    private readonly Dictionary<string, HostDistributionEntry> entries = new(StringComparer.Ordinal);
    private readonly Dictionary<Pid, HostDistributionEntry> controllers = new();
    private ulong generation;
    private bool closed;

    public HostDistribution(ProcessRuntime runtime, long maximumQueuedPayloadBytes, int maximumQueuedBuffers)
    {
        ArgumentNullException.ThrowIfNull(runtime);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(maximumQueuedPayloadBytes);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(maximumQueuedBuffers);
        this.runtime = runtime;
        this.maximumQueuedPayloadBytes = maximumQueuedPayloadBytes;
        this.maximumQueuedBuffers = maximumQueuedBuffers;
    }

    public HostDistributionHandle Attach(string channel, ProcessContext controller)
    {
        ArgumentException.ThrowIfNullOrEmpty(channel);
        ArgumentNullException.ThrowIfNull(controller);
        HostDistributionHandle handle;
        lock (gate)
        {
            ObjectDisposedException.ThrowIf(closed, this);
            if (!ReferenceEquals(controller.Runtime, runtime))
                throw new InvalidOperationException(HostDistributionDiagnostics.Owner);
            RemoveCompleted();
            RequireLive(controller);
            if (entries.ContainsKey(channel) || controllers.ContainsKey(controller.Self))
                throw new InvalidOperationException(HostDistributionDiagnostics.Attached);
            var entry = new HostDistributionEntry(
                channel,
                checked(++generation),
                controller
            );
            entries.Add(channel, entry);
            controllers.Add(controller.Self, entry);
            handle = new(this, entry);
        }
        _ = controller.Done.Task.ContinueWith(
            _ => Close(handle),
            CancellationToken.None,
            TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default
        );

        return handle;
    }

    public HostDistributionLease Acquire(HostDistributionHandle handle)
    {
        lock (gate)
            _ = Require(handle);

        return new(handle);
    }

    public HostDistributionSnapshot Snapshot(HostDistributionHandle handle)
    {
        lock (gate)
        {
            var entry = Require(handle);

            return new(
                entry.Generation,
                entry.Controller.Self,
                entry.InputHandler,
                entry.GetSize,
                entry.NotificationArmed,
                entry.InputPackets,
                entry.OutputPackets,
                entry.QueuedPayloadBytes,
                entry.Output.Count
            );
        }
    }

    public bool SetGetSize(HostDistributionHandle handle, ProcessContext caller, bool value)
    {
        lock (gate)
        {
            var entry = RequireController(handle, caller);
            bool previous = entry.GetSize;
            entry.GetSize = value;

            return previous;
        }
    }

    public bool GetSize(HostDistributionHandle handle, ProcessContext caller)
    {
        lock (gate)
            return RequireController(handle, caller).GetSize;
    }

    public void SetInputHandler(HostDistributionHandle handle, ProcessContext caller, Pid handler)
    {
        ArgumentNullException.ThrowIfNull(handler);
        lock (gate)
        {
            var entry = RequireController(handle, caller);
            if (handler.Node != runtime.Node || handler.Creation != caller.Self.Creation)
                throw new InvalidOperationException(HostDistributionDiagnostics.Identity);
            entry.InputHandler = handler;
        }
    }

    public void RecordAcceptedHostInput(HostDistributionHandle handle, ProcessContext caller)
    {
        lock (gate)
        {
            var entry = Require(handle);
            RequireCaller(caller);
            if (!caller.Self.Equals(entry.InputHandler))
                throw new InvalidOperationException(HostDistributionDiagnostics.InputHandler);
            entry.InputPackets = checked(entry.InputPackets + 1);
        }
    }

    public void ArmNotification(HostDistributionHandle handle, ProcessContext caller)
    {
        Pid? notify = null;
        lock (gate)
        {
            var entry = RequireController(handle, caller);
            if (!entry.NotificationArmed)
            {
                if (entry.Output.Count != 0)
                    notify = entry.Controller.Self;
                else
                    entry.NotificationArmed = true;
            }
        }
        Notify(notify);
    }

    public bool TryEnqueueFinalizedHostBuffer(HostDistributionHandle handle, HostDistributionBuffer buffer)
    {
        ArgumentNullException.ThrowIfNull(buffer);
        Pid? notify = null;
        lock (gate)
        {
            var entry = Require(handle);
            if (entry.Output.Count >= maximumQueuedBuffers || buffer.PayloadBytes > maximumQueuedPayloadBytes - entry.QueuedPayloadBytes)
                return false;
            entry.Output.Enqueue(buffer);
            entry.QueuedPayloadBytes += buffer.PayloadBytes;
            if (entry.NotificationArmed)
            {
                entry.NotificationArmed = false;
                notify = entry.Controller.Self;
            }
        }
        Notify(notify);

        return true;
    }

    public HostDistributionBuffer? TakeFinalizedHostBuffer(
        HostDistributionHandle handle,
        ProcessContext caller,
        out bool getSize
    )
    {
        lock (gate)
        {
            var entry = RequireController(handle, caller);
            getSize = entry.GetSize;
            if (!entry.Output.TryPeek(out var buffer))
                return null;
            long count = checked(entry.OutputPackets + 1);
            _ = entry.Output.Dequeue();
            entry.QueuedPayloadBytes -= buffer.PayloadBytes;
            entry.OutputPackets = count;

            return buffer;
        }
    }

    public void Close(HostDistributionHandle handle)
    {
        ArgumentNullException.ThrowIfNull(handle);
        lock (gate)
        {
            if (!ReferenceEquals(handle.Owner, this))
                throw new InvalidOperationException(HostDistributionDiagnostics.ForeignHandle);
            Retire(handle.Entry);
        }
    }

    public void Dispose()
    {
        lock (gate)
        {
            closed = true;
            foreach (var entry in entries.Values.ToArray())
                Retire(entry);
        }
    }

    private HostDistributionEntry Require(HostDistributionHandle handle)
    {
        ArgumentNullException.ThrowIfNull(handle);
        if (!ReferenceEquals(handle.Owner, this))
            throw new InvalidOperationException(HostDistributionDiagnostics.ForeignHandle);
        var entry = handle.Entry;
        if (closed || entry.Closed || !entries.TryGetValue(entry.Channel, out var current) || !ReferenceEquals(current, entry))
            throw new InvalidOperationException(HostDistributionDiagnostics.Closed);
        RequireLive(entry.Controller);

        return entry;
    }

    private HostDistributionEntry RequireController(HostDistributionHandle handle, ProcessContext caller)
    {
        var entry = Require(handle);
        RequireCaller(caller);
        if (!ReferenceEquals(entry.Controller, caller))
            throw new InvalidOperationException(HostDistributionDiagnostics.Controller);

        return entry;
    }

    private void RequireCaller(ProcessContext caller)
    {
        ArgumentNullException.ThrowIfNull(caller);
        if (!ReferenceEquals(caller.Runtime, runtime))
            throw new InvalidOperationException(HostDistributionDiagnostics.Owner);
        RequireLive(caller);
    }

    private void RequireLive(ProcessContext controller)
    {
        if (runtime.IsHaltRequested || controller.Stop.IsCancellationRequested || controller.Done.Task.IsCompleted || !runtime.IsAlive(controller.Self))
            throw new InvalidOperationException(HostDistributionDiagnostics.Closed);
    }

    private void RemoveCompleted()
    {
        foreach (var entry in entries.Values.ToArray())
            if (entry.Controller.Stop.IsCancellationRequested || entry.Controller.Done.Task.IsCompleted || !runtime.IsAlive(entry.Controller.Self))
                Retire(entry);
    }

    private void Retire(HostDistributionEntry entry)
    {
        if (entry.Closed)
            return;
        entry.Closed = true;
        entry.NotificationArmed = false;
        entry.Output.Clear();
        entry.QueuedPayloadBytes = 0;
        if (entries.TryGetValue(entry.Channel, out var current) && ReferenceEquals(current, entry))
            entries.Remove(entry.Channel);
        if (controllers.TryGetValue(entry.Controller.Self, out current) && ReferenceEquals(current, entry))
            controllers.Remove(entry.Controller.Self);
    }

    private void Notify(Pid? controller)
    {
        if (controller is not null)
            runtime.SendSystem(controller, HostDistributionAtoms.Data);
    }
}

namespace Erlang;

internal static class HostDistributionAtoms
{
    internal const string DataName = "dist_data";
    internal static readonly Atom Data = Term.A(DataName);
}

using System.Collections.ObjectModel;

namespace Erlang;

public sealed class HostDistributionBuffer
{
    public HostDistributionBuffer(IEnumerable<ReadOnlyMemory<byte>> segments)
    {
        ArgumentNullException.ThrowIfNull(segments);
        var snapshot = new List<BitString>();
        long size = 0;
        foreach (var segment in segments)
        {
            snapshot.Add(new BitString(segment.Span));
            size = checked(size + segment.Length);
        }
        Segments = new ReadOnlyCollection<BitString>(snapshot);
        PayloadBytes = size;
    }

    public IReadOnlyList<BitString> Segments { get; }
    public long PayloadBytes { get; }
}

namespace Erlang;

internal static class HostDistributionDiagnostics
{
    internal const string Closed = "The HOST distribution channel or lease is closed";
    internal const string Owner = "The HOST distribution controller belongs to another runtime";
    internal const string Controller = "The caller does not control this HOST distribution channel";
    internal const string InputHandler = "The caller is not the HOST distribution input handler";
    internal const string Attached = "The HOST channel or controller is already attached";
    internal const string ForeignHandle = "The HOST distribution handle belongs to another manager";
    internal const string Identity = "The HOST input handler must have a local process identity";
}

namespace Erlang;

internal sealed class HostDistributionEntry(
    string channel,
    ulong generation,
    ProcessContext controller
)
{
    internal string Channel { get; } = channel;
    internal ulong Generation { get; } = generation;
    internal ProcessContext Controller { get; } = controller;
    internal Pid InputHandler { get; set; } = controller.Self;
    internal Queue<HostDistributionBuffer> Output { get; } = new();
    internal bool Closed { get; set; }
    internal bool GetSize { get; set; }
    internal bool NotificationArmed { get; set; }
    internal long InputPackets { get; set; }
    internal long OutputPackets { get; set; }
    internal long QueuedPayloadBytes { get; set; }
}

namespace Erlang;

public sealed class HostDistributionHandle
{
    internal HostDistributionHandle(HostDistribution owner, HostDistributionEntry entry)
    {
        Owner = owner;
        Entry = entry;
    }

    internal HostDistribution Owner { get; }
    internal HostDistributionEntry Entry { get; }
    public ulong Generation => Entry.Generation;
}

namespace Erlang;

public sealed class HostDistributionLease : IDisposable
{
    private HostDistributionHandle? handle;

    internal HostDistributionLease(HostDistributionHandle handle) => this.handle = handle;

    public HostDistributionSnapshot Snapshot()
    {
        var current = Volatile.Read(ref handle) ?? throw new ObjectDisposedException(nameof(HostDistributionLease));

        return current.Owner.Snapshot(current);
    }

    public void Dispose() => Interlocked.Exchange(ref handle, null);
}

namespace Erlang;

public sealed record HostDistributionSnapshot(
    ulong Generation,
    Pid Controller,
    Pid InputHandler,
    bool GetSize,
    bool NotificationArmed,
    long AcceptedInputPackets,
    long ConsumedOutputPackets,
    long QueuedPayloadBytes,
    int QueuedBuffers
);

using Erlang;

internal static class HostDistributionAdditionalChecks
{
    internal static async Task Run()
    {
        await OwnershipAndInputTransfer();
        await QueueLimitsAndRaces();
        await DeathAndReplacement();
        await HaltAndRuntimeDisposal();
    }

    private static async Task OwnershipAndInputTransfer()
    {
        await using var runtime = new ProcessRuntime();
        await using var foreignRuntime = new ProcessRuntime(HostDistributionTestNames.ForeignNode);
        using var manager = NewManager(runtime);
        await using var controller = new HostDistributionTestActor(runtime);
        await using var input = new HostDistributionTestActor(runtime);
        await using var foreign = new HostDistributionTestActor(foreignRuntime);
        var handle = await controller.Invoke(context => manager.Attach(HostDistributionTestNames.Channel, context));
        await input.Invoke(context => Reject(() => manager.GetSize(handle, context)));
        await foreign.Invoke(context => Reject(() => manager.GetSize(handle, context)));
        await foreign.Invoke(context => Reject(() => manager.Attach(HostDistributionTestNames.OtherChannel, context)));
        await controller.Invoke(context =>
        {
            manager.SetInputHandler(handle, context, input.Process.Pid);

            return true;
        });
        await controller.Invoke(context => Reject(() => manager.RecordAcceptedHostInput(handle, context)));
        await input.Invoke(context =>
        {
            manager.RecordAcceptedHostInput(handle, context);

            return true;
        });
        await foreign.Invoke(context => Reject(() => manager.RecordAcceptedHostInput(handle, context)));
        Check(manager.Snapshot(handle).AcceptedInputPackets == 1);
        await controller.Invoke(context => Reject(() => manager.SetInputHandler(handle, context, foreign.Process.Pid)));
        Check(manager.Snapshot(handle).InputHandler.Equals(input.Process.Pid));
    }

    private static async Task QueueLimitsAndRaces()
    {
        await using var runtime = new ProcessRuntime();
        using var manager = NewManager(runtime);
        await using var controller = new HostDistributionTestActor(runtime);
        var handle = await controller.Invoke(context => manager.Attach(HostDistributionTestNames.Channel, context));
        var empty = new HostDistributionBuffer([]);
        Check(manager.TryEnqueueFinalizedHostBuffer(handle, empty));
        Check(manager.TryEnqueueFinalizedHostBuffer(handle, empty));
        Check(!manager.TryEnqueueFinalizedHostBuffer(handle, empty));
        Check(manager.Snapshot(handle).QueuedPayloadBytes == 0);
        await controller.Invoke(context =>
        {
            Check(manager.TakeFinalizedHostBuffer(handle, context, out _) == empty);
            Check(manager.TakeFinalizedHostBuffer(handle, context, out _) == empty);

            return true;
        });
        var full = new HostDistributionBuffer([new byte[HostDistributionTestNames.PayloadLimit].AsMemory()]);
        Check(manager.TryEnqueueFinalizedHostBuffer(handle, full));
        Check(!manager.TryEnqueueFinalizedHostBuffer(handle, new HostDistributionBuffer([new byte[1].AsMemory()])));
        await controller.Invoke(context => manager.TakeFinalizedHostBuffer(handle, context, out _));
        var packet = new HostDistributionBuffer([new byte[] { 7 }.AsMemory()]);
        for (int iteration = 0; iteration < HostDistributionTestNames.RaceRepetitions; iteration++)
        {
            var start = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var armReady = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var enqueueReady = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var arm = controller.InvokeAsync(async context =>
            {
                armReady.SetResult();
                await start.Task;
                manager.ArmNotification(handle, context);

                return true;
            });
            var enqueue = Task.Run(async () =>
            {
                enqueueReady.SetResult();
                await start.Task;

                return manager.TryEnqueueFinalizedHostBuffer(handle, packet);
            });
            await Task.WhenAll(armReady.Task, enqueueReady.Task).WaitAsync(HostDistributionTestNames.Deadline);
            start.SetResult();
            await Task.WhenAll(arm, enqueue).WaitAsync(HostDistributionTestNames.Deadline);
            Check(await enqueue);
            await controller.InvokeAsync(async context =>
            {
                var notice = await context.ReceiveAsync(
                    term => term is Atom { Name: HostDistributionTestNames.Data } ? term : null,
                    HostDistributionTestNames.Deadline
                );
                Check(notice is Atom);
                Check(context.Mailbox.Count == 0);
                Check(manager.TakeFinalizedHostBuffer(handle, context, out _) == packet);
                Check(manager.TakeFinalizedHostBuffer(handle, context, out _) is null);

                return true;
            });
        }
        Check(manager.Snapshot(handle).QueuedPayloadBytes == 0);
    }

    private static async Task DeathAndReplacement()
    {
        await using var runtime = new ProcessRuntime();
        using var manager = NewManager(runtime);
        await using var controller = new HostDistributionTestActor(runtime);
        await using var sender = new HostDistributionTestActor(runtime);
        var handle = await controller.Invoke(context => manager.Attach(HostDistributionTestNames.Channel, context));
        using var lease = manager.Acquire(handle);
        Check(manager.TryEnqueueFinalizedHostBuffer(handle, new HostDistributionBuffer([new byte[] { 1 }.AsMemory()])));
        var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var release = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var blocked = controller.InvokeAsync(async context =>
        {
            entered.SetResult();
            await release.Task;

            return Reject(() => manager.GetSize(handle, context));
        });
        await entered.Task.WaitAsync(HostDistributionTestNames.Deadline);
        try
        {
            await sender.Invoke(context =>
            {
                runtime.Exit(context, controller.Process.Pid, Term.A(HostDistributionTestNames.Killed));

                return true;
            });
            await controller.Process.Completion.WaitAsync(HostDistributionTestNames.Deadline);
            Check(Reject(() => lease.Snapshot()));
            await using var replacement = new HostDistributionTestActor(runtime);
            var newer = await replacement.Invoke(context => manager.Attach(HostDistributionTestNames.Channel, context));
            Check(newer.Generation > handle.Generation);
            Check(manager.Snapshot(newer).QueuedPayloadBytes == 0);
            manager.Close(handle);
            release.SetResult();
            Check(await blocked);
            Check(manager.Snapshot(newer).QueuedBuffers == 0);
        }
        finally
        {
            release.TrySetResult();
        }
    }

    private static async Task HaltAndRuntimeDisposal()
    {
        await using var runtime = new ProcessRuntime();
        using var manager = NewManager(runtime);
        await using var controller = new HostDistributionTestActor(runtime);
        var handle = await controller.Invoke(context => manager.Attach(HostDistributionTestNames.Channel, context));
        using var lease = manager.Acquire(handle);
        var halt = runtime.RequestImmediateHalt(0);
        Check(Reject(() => lease.Snapshot()));
        await halt.WaitAsync(HostDistributionTestNames.Deadline);
        await runtime.HaltQuiescence.WaitAsync(HostDistributionTestNames.Deadline);
        await using var disposedRuntime = new ProcessRuntime();
        using var disposedManager = NewManager(disposedRuntime);
        await using var disposedController = new HostDistributionTestActor(disposedRuntime);
        var disposedHandle = await disposedController.Invoke(context => disposedManager.Attach(HostDistributionTestNames.Channel, context));
        await disposedRuntime.DisposeAsync();
        Check(Reject(() => disposedManager.Snapshot(disposedHandle)));
        disposedManager.Dispose();
    }

    private static HostDistribution NewManager(ProcessRuntime runtime)
        => new(
            runtime,
            HostDistributionTestNames.PayloadLimit,
            HostDistributionTestNames.BufferLimit
        );

    private static bool Reject(Action action)
    {
        try
        {
            action();
        }
        catch (InvalidOperationException)
        {
            return true;
        }

        throw new Exception(HostDistributionTestNames.Failure);
    }

    private static void Check(bool condition)
    {
        if (!condition)
            throw new InvalidOperationException(HostDistributionTestNames.Failure);
    }
}

using Erlang;

internal static class HostDistributionChecks
{
    internal static async Task Run()
    {
        await using var runtime = new ProcessRuntime();
        using var manager = new HostDistribution(
            runtime,
            HostDistributionTestNames.PayloadLimit,
            HostDistributionTestNames.BufferLimit
        );
        using var other = new HostDistribution(
            runtime,
            HostDistributionTestNames.PayloadLimit,
            HostDistributionTestNames.BufferLimit
        );
        var ready = new TaskCompletionSource<ProcessContext>(TaskCreationOptions.RunContinuationsAsynchronously);
        var done = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var process = runtime.Spawn(async context =>
        {
            ready.SetResult(context);
            await done.Task.WaitAsync(context.Cancellation);

            return Nil.Value;
        });
        var caller = await ready.Task.WaitAsync(HostDistributionTestNames.Deadline);
        var handle = manager.Attach(HostDistributionTestNames.Channel, caller);
        using var lease = manager.Acquire(handle);
        Check(!manager.GetSize(handle, caller));
        Check(!manager.SetGetSize(handle, caller, true));
        Check(manager.GetSize(handle, caller));
        Check(manager.SetGetSize(handle, caller, false));
        Reject(() => manager.Attach(HostDistributionTestNames.OtherChannel, caller));
        Reject(() => other.Snapshot(handle));
        manager.ArmNotification(handle, caller);
        manager.ArmNotification(handle, caller);
        Check(lease.Snapshot().NotificationArmed);
        byte[] bytes = [1, 2, 3];
        var buffer = new HostDistributionBuffer([bytes.AsMemory()]);
        bytes[0] = 9;
        Check(manager.TryEnqueueFinalizedHostBuffer(handle, buffer));
        Check(manager.TryEnqueueFinalizedHostBuffer(handle, buffer));
        Check(!manager.TryEnqueueFinalizedHostBuffer(handle, buffer));
        var notice = await caller.ReceiveAsync(
            term => term is Atom { Name: HostDistributionTestNames.Data } ? term : null,
            HostDistributionTestNames.Deadline
        );
        Check(notice is Atom);
        Check(caller.Mailbox.Count == 0);
        var snapshot = lease.Snapshot();
        Check(snapshot.QueuedBuffers == 2 && snapshot.QueuedPayloadBytes == 6 && !snapshot.NotificationArmed);
        Check(manager.TakeFinalizedHostBuffer(handle, caller, out bool sized) == buffer && !sized);
        Check(buffer.Segments[0].ToArray().SequenceEqual(new byte[] { 1, 2, 3 }));
        byte[] exported = buffer.Segments[0].ToArray();
        exported[0] = 9;
        Check(buffer.Segments[0].ToArray().SequenceEqual(new byte[] { 1, 2, 3 }));
        Check(manager.TakeFinalizedHostBuffer(handle, caller, out _) == buffer);
        Check(manager.TakeFinalizedHostBuffer(handle, caller, out _) is null);
        manager.RecordAcceptedHostInput(handle, caller);
        snapshot = lease.Snapshot();
        Check(snapshot.AcceptedInputPackets == 1 && snapshot.ConsumedOutputPackets == 2 && snapshot.QueuedPayloadBytes == 0);
        manager.Close(handle);
        Reject(() => lease.Snapshot());
        var replacement = manager.Attach(HostDistributionTestNames.Channel, caller);
        Check(replacement.Generation > handle.Generation);
        manager.Close(handle);
        Check(manager.Snapshot(replacement).QueuedBuffers == 0);
        lease.Dispose();
        RejectDisposed(() => lease.Snapshot());
        done.SetResult();
        await process.Completion.WaitAsync(HostDistributionTestNames.Deadline);
        Reject(() => manager.Snapshot(replacement));
        manager.Dispose();
        await HostDistributionAdditionalChecks.Run();
    }

    private static void Check(bool condition)
    {
        if (!condition)
            throw new InvalidOperationException(HostDistributionTestNames.Failure);
    }

    private static void Reject(Action action)
    {
        try
        {
            action();
        }
        catch (InvalidOperationException)
        {
            return;
        }

        throw new Exception(HostDistributionTestNames.Failure);
    }

    private static void RejectDisposed(Action action)
    {
        try
        {
            action();
        }
        catch (ObjectDisposedException)
        {
            return;
        }

        throw new Exception(HostDistributionTestNames.Failure);
    }
}

using Erlang;
using System.Threading.Channels;

internal sealed class HostDistributionTestActor : IAsyncDisposable
{
    private readonly Channel<Func<ProcessContext, Task>> commands = Channel.CreateUnbounded<Func<ProcessContext, Task>>();
    private readonly TaskCompletionSource<ProcessContext> ready = new(TaskCreationOptions.RunContinuationsAsynchronously);

    internal HostDistributionTestActor(ProcessRuntime runtime)
    {
        Process = runtime.Spawn(async context =>
        {
            ready.TrySetResult(context);
            try
            {
                await foreach (var command in commands.Reader.ReadAllAsync(context.Cancellation))
                    await command(context);
            }
            finally
            {
                commands.Writer.TryComplete();
            }

            return Nil.Value;
        });
    }

    internal ProcessHandle Process { get; }
    internal Task<ProcessContext> Ready => ready.Task;

    internal Task<T> Invoke<T>(Func<ProcessContext, T> command)
        => InvokeAsync(context => Task.FromResult(command(context)));

    internal async Task<T> InvokeAsync<T>(Func<ProcessContext, Task<T>> command)
    {
        var result = new TaskCompletionSource<T>(TaskCreationOptions.RunContinuationsAsynchronously);
        await commands.Writer.WriteAsync(async context =>
        {
            try
            {
                result.TrySetResult(await command(context));
            }
            catch (Exception exception)
            {
                result.TrySetException(exception);
            }
        });

        return await result.Task.WaitAsync(HostDistributionTestNames.Deadline);
    }

    public async ValueTask DisposeAsync()
    {
        commands.Writer.TryComplete();
        await Process.Completion.WaitAsync(HostDistributionTestNames.Deadline);
    }
}

internal static class HostDistributionTestNames
{
    internal const string Channel = "owned-host-test-channel";
    internal const string OtherChannel = "other-host-test-channel";
    internal const string Data = "dist_data";
    internal const string Failure = "HOST distribution focus assertion failed";
    internal const string Killed = "kill";
    internal const string ForeignNode = "other-host-runtime@localhost";
    internal const int PayloadLimit = 8;
    internal const int BufferLimit = 2;
    internal const int RaceRepetitions = 64;
    internal static readonly TimeSpan Deadline = TimeSpan.FromSeconds(10);
}

using System.Text.Json;

await HostDistributionChecks.Run();
Console.WriteLine(JsonSerializer.Serialize(new { Passed = true, NativeExecutions = 0, RegisteredExportsAdded = 0 }));
